object Solution { def findMissingRanges(nums: Array[Int], lower: Int, upper: Int): List[List[Int]] = { val result = scala.collection.mutable.ListBuffer[List[Int]](); var previous = lower.toLong - 1; for (i <- 0 to nums.length) { val current = if (i == nums.length) upper.toLong + 1 else nums(i).toLong; if (current - previous >= 2) result += List((previous + 1).toInt, (current - 1).toInt); previous = current }; result.toList } }